import { Component, ViewChild, viewChild } from '@angular/core';
import { Credito } from '../../models/credito.model';
import { CreditoService } from '../../controllers/credito.service';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { UtilsService } from '../../services/utils.service';
import { FormularioFlotanteComponent } from '../../shared/formulario-flotante/formulario-flotante.component';
import { AutocompleteFieldComponent } from "../../shared/generic-form/autocomplete-field/autocomplete-field.component";
import { FormsModule } from '@angular/forms';
import { CreditoAbono } from '../../models/credito.abono';
import { CreditoAbonoService } from '../../controllers/credito.abono.service';
import { CurrencyPipe, DatePipe } from '@angular/common';
import { LocalStorageService } from '../../services/localStorage/local-storage.service';
import { EstadoCuentaService } from '../../controllers/estado.cuenta.service';
import { EstadoCuenta, UtilsEstadoCuentaService } from '../../main/estado-cuenta/services/utils-estado-cuenta.service';
import { FileInput, FileInputComponent } from "../../shared/file-input/file-input.component";
import { VanillaDialogService } from '../../services/vanilla-dialog/vanilla-dialog.service';
import { TableRow } from '../../shared/tabla/tabla.component';
import { PagoCargaMasivaService } from '../../controllers/pago.carga.masiva.service';

@Component({
    selector: 'app-abono',
    imports: [
    RouterLink,
    FormsModule,
    FormularioFlotanteComponent,
    CurrencyPipe,
    DatePipe,
    FileInputComponent
],
    templateUrl: './abono.component.html',
    styleUrl: './abono.component.css'
})
export class AbonoComponent {
  @ViewChild('fileInput')
  fileInput:FileInputComponent | undefined
  credito_id?:number
  credito?:Credito
  abonos:(CreditoAbono&TableRow)[]=[]
  abono:Partial<CreditoAbono>={}
  showAdd:boolean=false
  ultimoEstado?:EstadoCuenta
  showDeleteForm:boolean=false
  nota:string=''
  formExtra={id:0}

  constructor(
    public abonoController: CreditoAbonoService,
    private creditoController: CreditoService,
    private route:ActivatedRoute,
    public utils: UtilsService,
    private utilsEstadoCuenta:UtilsEstadoCuentaService,
    private storage:LocalStorageService,
    private dialog:VanillaDialogService,
    private storageService: LocalStorageService,
    private pagoCargaMasivaService: PagoCargaMasivaService,
  ){}

  ngOnInit(){
    this.route.paramMap.subscribe(async (params)=>{
      const id= this.utils.intOrNull(params.get('credito_id'))
      if(id){
        this.setCreditoById(id)
      }
    })
  }

  public editar(abono: (CreditoAbono&TableRow)){
    const user = this.storageService.getUser()
    if(user.nombre!=='ROOT') return;
    abono.fecha= abono.fecha.substring(0,10)
    abono.isEdit=true
  }

  public async save(abono:CreditoAbono&TableRow){
    abono.fecha= abono.fecha.substring(0,10)
    await this.abonoController.update(abono.id, { fecha:abono.fecha })
    abono.isEdit=false
  }

  private async setCreditoById(id:number){
    if(id === this.credito?.id) return;
    this.credito_id=id
    this.credito= await this.creditoController.find(id,['creditosPagos','abonos','abonos.pagosCargasMasivas','abonos.usuarios','productosFinancieros.plazos', 'estadoCuenta', 'convenios.conveniosPagos'])
    this.abonos= this.credito?.abonos??[]
    this.ultimoEstado= this.credito?.estado_cuenta
    console.log(this.credito, this.ultimoEstado)
  }

  new(){
    this.abono={}
    this.abono.fecha= new Date().toISOString().substring(0,10)
    this.showAdd=true
  }

  totalAbonos(){
    return this.abonos
    .filter((item)=> !item.deleted_at)
    .reduce((acc,item)=>{
      return acc+item.monto
    },0)
  }

  edit(row:CreditoAbono){
    this.abono=row
    this.showAdd=true
  }

  deleteForm(abono:CreditoAbono){
    this.nota=''
    this.showDeleteForm=true
    this.abono=abono
  }

  async deleteAbono() {
    const abono = this.abono as CreditoAbono;
    if (await this.abonoController.switch(abono, { nota: this.nota })) {
      this.setCreditoById(this.credito!.id);
    }
    this.abono = {};
    this.showDeleteForm = false;
  }


  async submit(){
    if(!this.fileInput?.file){
      this.dialog.show({
        title:'Algo salió mal',
        tipo:'danger',
        body:'Agrega un documento o evidencia del pago.'
      })
      console.error('FORM INVALIDO')
      return;
    }
    const data=await this.abonoController.createOrUpdate({
      ...this.abono,
      credito_id:this.credito_id
    })
    if(data && data.id){
      this.abono = data
      this.formExtra.id = data.id
      this.fileInput?.upload()
      this.abono.usuarios=this.storage.getUser()
      this.abonos.push(data as CreditoAbono)
      this.utilsEstadoCuenta.calculateEstadoDeCuenta(this.credito,true)
      this.showAdd=false
      this.setCreditoById(this.credito!.id)
    }
  }
}
